{
  const reminders = generateProfileCompletionReminders([]);
  assert(reminders.length === 0, "No profile completion cards with zero contacts");
}

// ─── Test 13: Profile completion cards do NOT appear in generateReminders ───
console.log("\nTest 13: Profile completion cards are absent from generateReminders (home/suggestions feed)");
{
  const contacts: Contact[] = [
    makeContact({ id: "c1", circleLevel: 1, birthday: undefined, labels: [], interests: [] }),
  ];
  const reminders = generateReminders(contacts);
  const pcCards = reminders.filter((r) => r.type.startsWith("profile-completion"));
  assert(pcCards.length === 0, "generateReminders contains no profile-completion cards");
}

// ─── Tests 14-20: card dismiss logic via generateProfileCompletionReminders ───

function bellReminders(
  contacts: Contact[],
  dismissedIds: Set<string> = new Set(),
) {
  return generateProfileCompletionReminders(contacts).filter((r) => !dismissedIds.has(r.id));
}

console.log("\nTest 14: Red card disappears from bell list after C1 birthday is added");
{
  const contacts: Contact[] = [
    makeContact({ id: "c1", circleLevel: 1, birthday: "03/15", labels: ["Family"], interests: ["Reading"] }),
    makeContact({ id: "c2", circleLevel: 2, birthday: "05/01", labels: ["Work"], interests: ["Gaming"] }),
  ];
  const card = bellReminders(contacts).find((r) => r.type === "profile-completion-high");
  assert(!card, "Red card disappears from bell list once C1 contact has a birthday");
}

console.log("\nTest 15: Orange card appears in bell list when C2 has no birthday");
{
  const contacts: Contact[] = [
    makeContact({ id: "c1", circleLevel: 1, birthday: "03/15", labels: ["Family"], interests: ["Running"] }),
    makeContact({ id: "c2", circleLevel: 2, birthday: undefined, labels: ["Work"], interests: ["Gaming"] }),
    makeContact({ id: "c3", circleLevel: 3, birthday: "11/22", labels: ["Neighbor"], interests: ["Movies"] }),
  ];
  const card = bellReminders(contacts).find((r) => r.type === "profile-completion-medium");
  assert(!!card, "Orange card appears in bell list when C2 contact is missing a birthday");
}

