console.log("\nTest 19: Dismissed profile-completion-high card is hidden");
{
  const contacts: Contact[] = [
    makeContact({ id: "c1", circleLevel: 1, birthday: undefined, labels: ["Family"], interests: ["Reading"] }),
  ];
  const before = bellReminders(contacts);
  assert(!!before.find((r) => r.type === "profile-completion-high"), "Red card visible before dismiss");
  const after = bellReminders(contacts, new Set(["profile-completion-high"]));
  assert(!after.find((r) => r.type === "profile-completion-high"), "Red card hidden after dismiss");
}

console.log("\nTest 20: Red card appears when C1 has no birthday, absent when C2 is the only issue");
{
  const contacts: Contact[] = [
    makeContact({ id: "c1", circleLevel: 1, birthday: undefined, labels: ["Family"], interests: ["Reading"] }),
    makeContact({ id: "c2", circleLevel: 2, birthday: "05/01", labels: ["Work"], interests: ["Gaming"] }),
  ];
  const cards = bellReminders(contacts);
  assert(!!cards.find((r) => r.type === "profile-completion-high"), "Red card present when C1 missing birthday");
  assert(!cards.find((r) => r.type === "profile-completion-medium"), "Orange card absent when C2 has birthday");
}

// ─── Summary ───
console.log(`\n=== Results: ${passed} passed, ${failed} failed ===\n`);
if (failed > 0) process.exit(1);
